/**
 * 作文题库 —— 中考作文题 26 道，让学生有题可写、有法可依。
 *
 * 覆盖四种命题形式：
 * - 命题作文 8 道：题面完整给出，训练抓题眼、定重心、控制叙述范围；
 * - 半命题作文 7 道：训练补题的取舍（补小不补大、补实不补虚、补熟不补生、补己不补人）；
 * - 材料作文 6 道：材料均为原创撰写或公有领域内容（如《老子》名句、提灯照路的民间寓言母题），
 *   不摘抄任何有版权的文章，训练提取、比较、定向三步立意；
 * - 话题作文 5 道：只给话题词，训练自限范围、自拟标题，避免空谈。
 *
 * 每一题都给出题目、审题（含最容易跑偏的两种理解）、三层立意（稳妥 / 有深度 / 新颖）、
 * 具体选材方向、可套用的结构与字数配比、易错点提醒，并附原创开头示例与点评、
 * 两道考查审题立意的选择题，学生可按「读题 → 立意 → 列提纲 → 写作 → 对照点评」完成一次完整练笔。
 *
 * 字段严格遵循 src/types.ts 中的 WritingLesson 接口。
 * content 段落约定：以 `## ` 开头视为小标题，正文内引号统一用「」，书名统一用《》。
 * 本文件中的开头示例与点评均为原创撰写，不摘抄任何现成作品或考场满分作文。
 */

