      '以「这一次，我长大了」为题，写一篇不少于六百字的记叙文。要求：结合自己的经历，写一件具体的事；文中不得出现真实的校名、人名。',
      '## 审题',
      '题目由两个关键成分组成：「这一次」限定事件的数量与性质，「长大了」限定文章必须写出变化。前者要求全文只写一次具体的事件，有明确的时间、地点与经过；后者要求写出心理或认识上的变化，而不是身体的长高、年龄的增加或技能的学会。',
      '最容易跑偏的第一种理解：把「长大」写成学会了某项本领，如第一次学会骑车、学会做菜、学会独自坐车。这类文章全篇都在写技能的练习过程，最后加一句「我长大了」，其实文中的变化只是「我会了」，与「我长大了」并不等同。所谓长大，是懂得了一件此前不懂的道理，是待人处事的方式变了。',
      '最容易跑偏的第二种理解：把「这一次」写成「这些年」。有同学开头写「从小到大，我经历过许多事」，中间并列三件事，每件事一百多字。这样一来事件没有一次是写透的，成长也就无从落实。题目里的「这一次」是一次具体的经历，它必须能回答「哪一天、在哪里、发生了什么」。',
      '还有一处隐性限制容易忽略：题目是「我」长大，全文必须用第一人称写自己的转变。如果文章大部分篇幅在写母亲如何辛苦、老师如何耐心，自己只是个旁观的记录者，那么「我」的成长就没有落点。写别人，是为了照见自己的变化。',
      '## 立意',
      '稳妥层：从被照顾的人变成照顾别人的人。写「我」第一次承担家务、第一次照看弟弟妹妹、第一次替大人分担一件具体的事，在做事的过程中体会到大人平日的不容易。这一层立意扎实好写，只要细节够，就能拿到中上的分数。适合写一段真实的家庭经历，把做事时的笨拙写足。',
      '有深度层：从只顾自己到看见别人。长大的标志不是自己变强了，而是终于看见了一直被忽略的人。例如某次整理房间时翻出母亲的体检单，某次吃饭时注意到父亲夹菜的手在抖，某次听见外婆在电话里说「我挺好的」。写这一层，事件可以是小事，但因为「我」的视线变了，文章的重量就完全不同。适合情感细腻、善于观察的同学。',
      '新颖层：长大是学会承认自己的有限与失败。大多数人把长大写成「我能行了」，如果反过来写「我终于敢说我不行」，就跳出了主流写法。可以写一次比赛失利后，主动向队友道歉并承认自己拖了后腿；也可以写一次主动放弃——放弃一直想要的那个位置，把它让给更合适的同学。承认失败、学会退让、懂得取舍，都是真正意义上的长大，这一层立意新颖而不偏题。',
      '三个层次的区别不在题材大小，而在「我」认识世界的方式有没有变。写完提纲后可以自问一句：把我文中的那件事换掉，结尾那句感悟还成立吗？如果照样成立，说明立意太泛，需要重新确定。',
      '## 选材',
      '方向一：妈妈出差一周，我第一次负责弟弟的早饭与作业。可以写的细节是冰箱门上贴着的纸条、煎糊的鸡蛋、弟弟赖床时我学着妈妈的语气说话、晚上检查作业时发现他一道题抄错了三遍。结尾可落在「我终于知道妈妈的晚上是怎么过的」。',
      '方向二：外公住院，我第一次陪妈妈在医院走廊过夜。可以写的细节是走廊里并排的塑料椅、半夜自动亮起的感应灯、妈妈在楼梯间偷偷抹眼泪又笑着回来、她把唯一的外套披在我身上。这件素材的关键触发物是妈妈那句「你先睡」。',
      '方向三：班级合唱比赛，我第一次把领唱的位置让给更合适的同学。可以写的细节是把练了三周的谱子折起来递给对方、比赛那天站在第二排为他数拍子、唱完后他跑过来抱我一下。成长体现在「我」主动承认别人比自己合适。',
      '方向四：搬家前整理旧物，我第一次把从小玩到大的玩具送给邻居家的小孩。可以写的细节是玩具箱底部的灰、褪色的贴纸、我在箱子里坐了很久、小孩接过去时的手很小。这件素材适合写「告别」意义上的长大。',
