      '第二段（约一百五十字）：交代「我」此前的状态，也就是对照面。写我以前是怎样被照顾的、怎样只顾自己的，用一两件小事说明，为后面的变化提供参照。这段不写成长，只写幼稚。',
      '第三段（约三百字）：事件展开，写足两处细节。一处是身体的感受，如烫到手、闻到味道、手心的汗；一处是看见的画面，如妈妈的侧脸、弟弟的睡姿。事件过程中「我」要遇到一次不顺，让成长显得来之不易。',
      '第四段（约一百二十字）：转折点。用一个具体的触发物完成认识上的转变，可以是一句话、一个动作或一件物品。这一段要短，写得克制，不要长篇抒情。',
      '第五段（约一百字）：收束点题，把「这一次」与「长大了」两个词都呼应到。写到具体行为的变化，例如以前把碗一推就走，这次主动收了桌子。全文按六百到八百字计，上述配比约为一百加一百五十加三百加一百二十加一百字。',
