      '某条老街要拓成双向四车道。规划图公示那天，街坊们发现十七号门前那棵两人合抱的老槐树正好立在路中央。有人主张伐掉，理由是树根已经顶裂了三户人家的院墙；也有人查出了树龄，说它比这条街还老。后来施工队改了设计，路面在树身两侧各让出一米，绿化带绕成一个浅浅的弧。槐树留下来了，只是那一段路基比别处窄，夜里开车经过的人都得慢一慢。',
      '## 审题',
