        '全文只写一束起决定作用的光，「那束」的唯一性不要被其他光源拆散。',
        '先写自己处在暗处的样子，暗处越具体，后面的光才越有分量。',
        '写光要写它照见了什么，如卷面上的红叉、地上的水洼，不要只写光很温暖。',
        '结尾让光再出现一次，与开头呼应，并落到一个具体的动作上。',
