        text: '成绩单摊在饭桌上，卷角被压在一只酱油瓶下面。父亲夹菜的筷子在半空停了一下，抬眼看我，不到两秒，就把目光收回到碗里去。那一眼很短，短到我几乎以为自己看错了。可我记得清清楚楚，他的眉毛没有皱，眼皮却往下垂了一点，像是不敢看我。那顿饭谁也没提分数，只有抽油烟机在厨房里嗡嗡地响。我扒了两口饭就回了房间，把门关得很响，然后在门后站着，认定他眼里全是失望。',
