        '让树有一次具体的动作参与叙事，如果实落下、枝子被锯、树影移过门槛。',
        '老屋至少写实一样东西，如门槛、灶台、窗上的塑料布。',
        '全文固定两三个亲人，人物一多，篇幅就会被切碎。',
