        text: '绳柄上有一道浅浅的刻痕，是我用指甲掐出来的。初一那个暑假，我每天傍晚在小区楼下的空地上练跳短绳，从三十一个开始。起初绳子总是甩到小腿上，啪啪一声，皮肉立刻起一道白印，一会儿就红了。第七天我停下来看那道印子，忽然想，这样跳下去到底有什么意思。楼上的灯一户户亮起来，有人把窗户推开看了一会儿又关上。我把绳子摔在水泥地上，站在原地看着它，站了很久。最后还是弯腰捡起来，重新握好，甩出去，第一下就被绊住。再来。',
