        '行囊在开头与结尾各出现一次，让读者看得见它在哪儿。',
        '不要写物品清单，集中笔墨写一件。',
        '如果要写「留下」的方向，必须在文中写出一次真实的犹豫。',
        '避免用「我懂得了感恩」之类的议论收尾，把话留给一个动作。',
