        title: '开头示例（按《把外婆的针线包装进行囊》补题）',
        text: '出发前一晚，外婆把那个铁盒放在我床头的作业本上。盒盖上的红漆磨掉了一块，边角发黑，按下去会发出很轻的一声响。她打开给我看：缠成团的各色线，插在布卷里的七号针，还有一小块剪下来的旧布，边上留着毛茬。她让我把校服上那颗掉了的纽扣缝上去。针在布里穿过时总往一边滑，我缝了三回，指尖被扎出一粒血珠。外婆没说话，只把线头在嘴边抿了一下，又递给我。缝好后她合上盖子，把它推到我面前，说了两个字：带着。',
        comment: '这段开头的长处在于把抽象的情感全部压在实物上。铁盒的红漆、缠成团的线、七号针、留着毛茬的旧布，四样东西构成一组看得见的画面，读者不必被告知外婆有多疼孩子。缝纽扣这一动作又让物与人发生关系：针总往一边滑、指尖扎出血珠，写出了笨拙，也写出了被耐心对待的经验。结尾「带着」两个字极简，留白到位。',
