        title: '开头示例（按《在外婆的灶台旁》补题）',
        text: '初三那年的冬天，我又一次站在外婆的灶台旁。灶台上摊着一张旧报纸，边角被油浸成深褐色，菜刀压在上面。外婆切南瓜，左手按住南瓜的一头。她照旧不说话，只在起锅前把火关小，把炒好的南瓜片往我碗里拨。这道菜我吃了十年：小学三年级我嫌它软塌塌的，把碗推到一边；初一那年寒假我学会了自己盛饭，却只顾着把配菜挑走，剩下的推给外婆。今天我把碗往前推了半寸，说：「外婆，你先夹。」她愣了一下，笑着用筷子尖挑起一小片，放进自己嘴里慢慢嚼。',
        comment: '这个开头用同一道菜串起三个时间节点，起手就立住了「慢慢」。旧报纸上被油浸出的深色、按住南瓜的左手，都是灶台旁才有的细节。两句回叙把前两次的反应压缩进来，一次推碗、一次只挑配菜，与今天把碗往前推半寸形成清楚的对照，变化不靠议论就立住了。结尾外婆愣了一下才夹菜的那一笔很好，说明她等这个动作等了很久。',
