        answer: 'C',
        explanation: '材料的关键句是「这盏灯照的不是我的路，是照给别人看的」，以及别人看见有光也就不会撞到他这一层解释，两者合起来才是内核：照亮别人与保护自己是同一个动作。A 项只取自我保护一层，丢掉了照亮别人；B 项把相互成全写成单向奉献，与盲人自己的解释相反；D 项脱离材料，谈的是公共设施。',
