        text: '翻开同桌的第一本错题本，能看见时间的形状。前二十页的字写得用力，横平竖直，每道题都恨不得抄两遍；翻到中间，字迹忽然潦草了，有一页只写了半道题，下面空着，旁边用铅笔注了四个字：明天再补。再往后，字又慢慢端正起来，只是颜色换成了蓝色。这本本子的封面已经起了毛边。他说写满第一本用了整整四个月，其中有两个星期他一次也没翻开它。可正是那两个星期之后的那个晚上，他坐回书桌前，把第一页翻开，重新看了一遍那道从一开始就做错的题。',
        comment: '这段开头好在两处：一是把抽象的积累换成可以看见的笔迹变化，字由用力到潦草，这本身就是毫末怎样长过去的过程；二是敢于写出有两个星期一次也没翻开这一笔，坚持里的中断被如实写下来，比通篇咬牙硬撑更真实。可以更好的是「时间的形状」一句稍显文气，与后面朴实的细节略有落差。',
